    ],
  },
  "date_gt_last14": {
    "offset": 0, "pageSize": 3,
    "fields": "id,name",
    "filters": [
      {"type": 21, "operator": "equal", "value": {"dateType": "thisWeek"}},
    ],
  },
}
for name, body in probes.items():
