(async () => {
  const token = '[токен убран]';
  async function comments(id) {
    const tries = [
      ['POST','/rest/comment/list', {offset:0,pageSize:15,fields:'id,description,dateTime,owner,type',task:{id}}],
      ['POST','/rest/task/'+id+'/comments/list', {offset:0,pageSize:15,fields:'id,description,dateTime,owner'}],
      ['GET','/rest/task/'+id+'/comments?fields=id,description,dateTime,owner&offset=0&pageSize=10', null],
    ];
    const res = [];
    for (const [m,p,b] of tries) {
      const r = await fetch('https://tonal.planfix.ru'+p, {method:m, headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',Accept:'application/json'}, body: b?JSON.stringify(b):undefined});
      const t = await r.text();
      res.push({m,p,status:r.status, body:t.slice(0,600)});
      if (r.ok && t.includes('success') && !t.includes('"comments":[]') && t.includes('description')) break;
    }
    return res;
  }
  const c33572 = await comments(33572);
  const c33570 = await comments(33570);
  return {c33572, c33570};
})()

